<hr><div class="table-responsive"><table class="table pos-standard-table" id="purchase-lines"><thead><tr><th style="width:42%">Product</th><th class="text-right">Qty</th><th class="text-right">Unit Cost</th><th class="text-right">Line Total</th><th></th></tr></thead><tbody><tr><td><select class="form-control" name="product_id[]" required><option value="">Select product</option>@foreach($products as $product)<option value="{{ $product->id }}">{{ $product->name }} - {{ $product->sku }}</option>@endforeach</select></td><td><input class="form-control qty text-right" type="number" step="0.001" name="quantity[]" value="1" required></td><td><input class="form-control cost text-right" type="number" step="0.01" name="unit_cost[]" value="0" required></td><td class="text-right line-total">0.00</td><td><button type="button" class="btn btn-danger remove-line">×</button></td></tr></tbody><tfoot><tr><th colspan="3" class="text-right">Total</th><th class="text-right" id="purchase-total">0.00</th><th><button type="button" class="btn btn-primary" id="add-line">Add Line</button></th></tr></tfoot></table></div></div></div>
