<script>
document.addEventListener('DOMContentLoaded',function(){function calc(){let t=0;document.querySelectorAll('#purchase-lines tbody tr').forEach(function(r){let q=parseFloat(r.querySelector('.qty').value||0),c=parseFloat(r.querySelector('.cost').value||0),v=q*c;t+=v;r.querySelector('.line-total').innerText=v.toFixed(2);});document.getElementById('purchase-total').innerText=t.toFixed(2);}document.addEventListener('input',function(e){if(e.target.classList.contains('qty')||e.target.classList.contains('cost'))calc();});document.getElementById('add-line').onclick=function(){let tr=document.querySelector('#purchase-lines tbody tr').cloneNode(true);tr.querySelectorAll('input').forEach(i=>i.value=i.classList.contains('qty')?'1':'0');tr.querySelector('select').selectedIndex=0;tr.querySelector('.line-total').innerText='0.00';document.querySelector('#purchase-lines tbody').appendChild(tr);calc();};document.addEventListener('click',function(e){if(e.target.classList.contains('remove-line')&&document.querySelectorAll('#purchase-lines tbody tr').length>1){e.target.closest('tr').remove();calc();}});calc();});
</script>
